-- 008: what the quiz grades with, and a study-aid block for book-solved questions.
-- answer_key = JSON, one entry per part the student answers (number / choice /
-- truefalse / expression / points); the contract is pipeline/answer_key_spec.md.
-- NULL means the app derives a one-part key from `answer` and `type` at load time.
-- takeaways = LaTeX body ending in its own `\hfill [Generated by ...]` line; shown
-- after the source's own `solution` when there is no generated solution.
-- Both are written only by the pipeline; the app never writes them.
ALTER TABLE questions ADD COLUMN answer_key TEXT;
ALTER TABLE questions ADD COLUMN takeaways TEXT;
